css:
.stack {
  display: flex;
  padding: 24px;
}

.avatar {
  position: relative;
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  margin-left: -16px; /* overlap the previous one */
  border: 3px solid #fafafa;
  border-radius: 50%;
  background: #3f3f46;
  color: #fafafa;
  font-weight: 600;
}

.stack .avatar:first-child {
  margin-left: 0;
}

.b { z-index: 3; background: #f97316; }
.c { z-index: 2; background: #2563eb; }
.d { z-index: 1; background: #16a34a; }
